const body = $json.body ?? $json;
const now = new Date().toISOString();
return [{
  json: {
    id: body.id || body.call_id || '',
    tenant_id: body.tenant_id || 'peskids',
    call_id: body.call_id || body.external_call_id || '',
    initiator_contact: body.initiator_contact || body.from || '',
    recipient_contact: body.recipient_contact || body.to || '',
    channel: body.channel || 'web',
    call_state: body.call_state || body.state || 'ringing',
    started_at: body.started_at || now,
    ended_at: body.ended_at || null,
    duration_seconds: body.duration_seconds || null,
    recording_url: body.recording_url || null,
    recording_id: body.recording_id || null,
    created_at: body.created_at || now,
    processed_at: now
  }
}];
